/**
 * Starlight route middleware: labels the prompt trail's per-base groups. Starlight names an autogenerated
 * group after its folder, so the `arch/` and `fedora/` folders would show as "arch" and "fedora".
 */
import { defineRouteMiddleware, type StarlightRouteData } from '@astrojs/starlight/route-data';

/** Sidebar labels for the base folders under src/content/docs/prompt-trail/. */
const baseLabels: Record<string, string> = { arch: 'Arch', fedora: 'Fedora' };

/** Relabels every group named after a base folder, at any depth. */
function relabel(entries: StarlightRouteData['sidebar']): void {
  for (const entry of entries) {
    if (entry.type !== 'group') continue;
    entry.label = baseLabels[entry.label] ?? entry.label;
    relabel(entry.entries);
  }
}

export const onRequest = defineRouteMiddleware(({ locals }) => relabel(locals.starlightRoute.sidebar));
